/// Its start and end swapped for a right-to-left layout (S2.4).
impl Mirror for IconPlacement {
    fn mirror(&mut self) {
        *self = match *self {
            IconPlacement::Leading => IconPlacement::Trailing,
            IconPlacement::Trailing => IconPlacement::Leading,
            other => other,
        };
    }
}

